parameters.jsCode:
const parsed = JSON.parse($input.first().json.result.content[0].text);
const g = (parsed.data && parsed.data.goalItemById) || {};

// Real current weekday/date in the user's timezone (America/New_York)
const dt = DateTime.now().setZone('America/New_York');
const weekday = dt.toFormat('cccc');
const dateStr = dt.toFormat('dd LLLL yyyy');
const split = {
  Sunday: 'Back, Shoulders, Wrist',
  Monday: 'Chest',
  Tuesday: 'Biceps, Wrist',
  Wednesday: 'Core and mild legs',
  Thursday: 'Rest',
  Friday: 'Cardio',
  Saturday: 'Intense legs'
};

// Route by the goal's CEO sub-area tag:
//   area:ceo:body -> running coach
//   area:ceo:soul -> meditation coach
//   area:ceo:mind (or anything else) -> elite lifting analyst
const tags = g.tags || [];
let route = 'lift'; // default
if (tags.includes('area:ceo:body')) {
  route = 'run';
} else if (tags.includes('area:ceo:soul')) {
  route = 'meditation';
}

// Planned context based on route
let planned = split[weekday] || 'Rest';
if (route === 'run') {
  planned = g.body || 'Easy jog';
} else if (route === 'meditation') {
  planned = g.body || 'Chakra & Flow practice';
}

parsed.dkgDate = dt.toFormat('dd-MM-yyyy');
parsed.weekday = weekday;
parsed.dateStr = dateStr;
parsed.planned = planned;
parsed.route = route;
return parsed;

const out = String($json.output || '');
const ctx = $('Context').first().json;
const g = (ctx.data && ctx.data.goalItemById) || {};
const route = ctx.route;
const acts = ctx.activities || [];
const stimuli = ctx.stimuli || [];

const metaMap = {
  run:        { area: 'Body', icon: '\u{1F3C3}', color: '#e67e22' },
  lift:       { area: 'Mind', icon: '\u{1F3CB}\u{FE0F}', color: '#2980b9' },
  meditation: { area: 'Soul', icon: '\u{1F9D8}', color: '#8e44ad' }
};
const meta = metaMap[route] || { area: 'CEO', icon: '⚡', color: '#16a085' };

const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');

const pm = out.match(/PROGRESS:\s*(\d{1,3})/i);
const progress = Math.max(0, Math.min(100, pm ? parseInt(pm[1], 10) : 50));
const summary = ((out.match(/SUMMARY:\s*(.+)/i) || [])[1] || '').trim();

function bullets(name) {
  const re = new RegExp('##\\s*' + name + '([\\s\\S]*?)(?=\\n##|$)', 'i');
  const sec = (out.match(re) || [])[1] || '';
  return sec.split('\n').map(l => l.trim()).filter(l => l.startsWith('-')).map(l => l.replace(/^-\s*/, ''));
}
const li = items => items.length
  ? items.map(i => '<li style="margin:6px 0;padding-left:4px;">' + esc(i) + '</li>').join('')
  : '<li style="margin:6px 0;color:#95a5a6;">Nothing logged</li>';

// ---------- SVG chart helpers ----------
const W = 600, H = 180, PL = 46, PR = 12, PT = 14, PB = 26;
function lineChart(title, labels, series, yFmt) {
  // series: [{name, color, values:[num|null]}]
  const all = series.flatMap(s => s.values).filter(v => v != null && isFinite(v));
  if (!all.length) return '';
  let ymin = Math.min(...all), ymax = Math.max(...all);
  if (ymin === ymax) { ymin -= 1; ymax += 1; }
  const pad = (ymax - ymin) * 0.12; ymin -= pad; ymax += pad;
  const n = labels.length;
  const x = i => n === 1 ? (PL + (W - PL - PR) / 2) : PL + (W - PL - PR) * i / (n - 1);
  const y = v => PT + (H - PT - PB) * (1 - (v - ymin) / (ymax - ymin));
  const fmt = yFmt || (v => Math.round(v * 10) / 10);
  let el = '';
  // gridlines + y labels
  for (let k = 0; k <= 3; k++) {
    const gv = ymin + (ymax - ymin) * k / 3, gy = y(gv);
    el += '<line x1="' + PL + '" y1="' + gy + '" x2="' + (W - PR) + '" y2="' + gy + '" stroke="#ecf0f1" stroke-width="1"/>';
    el += '<text x="' + (PL - 6) + '" y="' + (gy + 4) + '" font-size="10" fill="#95a5a6" text-anchor="end">' + fmt(gv) + '</text>';
  }
  // x labels: first, middle, last
  [0, Math.floor((n - 1) / 2), n - 1].filter((v, i, a) => a.indexOf(v) === i).forEach(i => {
    el += '<text x="' + x(i) + '" y="' + (H - 8) + '" font-size="10" fill="#95a5a6" text-anchor="middle">' + esc(labels[i] || '') + '</text>';
  });
  series.forEach(s => {
    const pts = s.values.map((v, i) => v == null ? null : [x(i), y(v)]);
    const path = pts.filter(Boolean).map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ');
    if (path) el += '<polyline points="' + path + '" fill="none" stroke="' + s.color + '" stroke-width="2.5" stroke-linejoin="round"/>';
    pts.forEach(p => { if (p) el += '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="3" fill="' + s.color + '"/>'; });
  });
  const legend = series.map(s =>
    '<span style="display:inline-block;margin-right:12px;font-size:12px;color:#57606f;">' +
    '<span style="display:inline-block;width:10px;height:10px;border-radius:5px;background:' + s.color + ';margin-right:4px;"></span>' +
    esc(s.name) + '</span>').join('');
  return '<div style="margin:14px 0;">' +
    '<div style="font-size:13px;font-weight:600;color:#2c3e50;margin-bottom:2px;">' + esc(title) + '</div>' +
    '<div>' + legend + '</div>' +
    '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;background:#fff;">' + el + '</svg></div>';
}

const dShort = iso => { const d = new Date(iso); return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0'); };
const byDateAsc = (a, b) => new Date(a.start_date_local) - new Date(b.start_date_local);

let charts = '';
if (route === 'run') {
  const runs = acts.filter(a => a.sport_type === 'Run' && a.distance > 0).sort(byDateAsc).slice(-12);
  if (runs.length) {
    const labels = runs.map(a => dShort(a.start_date_local));
    const pace = runs.map(a => (a.moving_time / 60) / (a.distance / 1000));
    charts += lineChart('Pace per run (min/km — lower is better)', labels,
      [{ name: 'Pace', color: '#e67e22', values: pace }], v => v.toFixed(1));
    charts += lineChart('Heart rate per run (bpm)', labels, [
      { name: 'Avg HR', color: '#e74c3c', values: runs.map(a => a.average_heartrate || null) },
      { name: 'Max HR', color: '#c0392b', values: runs.map(a => a.max_heartrate || null) }]);
    charts += lineChart('Distance per run (km)', labels,
      [{ name: 'Distance', color: '#16a085', values: runs.map(a => a.distance / 1000) }], v => v.toFixed(1));
  }
} else if (route === 'lift') {
  let wt = [];
  try { wt = ($('Lift Data').first().json.wtDetails || []); } catch (e) { wt = []; }
  const withT = wt.filter(w => w.tonnage != null);
  if (withT.length) {
    const unit = withT[0].unit || 'lbs';
    const labels = withT.map(w => dShort(w.date));
    charts += lineChart('Total weight lifted per session (' + unit + ')', labels,
      [{ name: 'Tonnage', color: '#2980b9', values: withT.map(w => w.tonnage) }],
      v => Math.round(v / 100) / 10 + 'k');
    const groups = {};
    withT.forEach(w => { (groups[w.name] = groups[w.name] || []).push(w); });
    Object.entries(groups).sort((a, b) => b[1].length - a[1].length).slice(0, 3).forEach(([name, sess]) => {
      if (sess.length >= 2) {
        charts += lineChart(name + ' — weight lifted (' + unit + ')', sess.map(w => dShort(w.date)),
          [{ name: 'Tonnage', color: '#8e44ad', values: sess.map(w => w.tonnage) }],
          v => Math.round(v / 100) / 10 + 'k');
      }
    });
    charts += lineChart('Exercises per session', labels,
      [{ name: 'Exercises', color: '#16a085', values: withT.map(w => w.exercises) }], v => Math.round(v));
  } else {
    const wt2 = acts.filter(a => a.sport_type === 'WeightTraining').sort(byDateAsc).slice(-10);
    if (wt2.length) {
      charts += lineChart('Session volume (min) — tonnage unavailable', wt2.map(a => dShort(a.start_date_local)),
        [{ name: 'Duration', color: '#2980b9', values: wt2.map(a => Math.round(a.moving_time / 60)) }], v => Math.round(v));
    }
  }
} else if (route === 'meditation') {
  if (stimuli.length) {
    charts += lineChart('Routine stimulus points — D/K/G this week', stimuli.map(s => s.date.slice(0, 5)), [
      { name: 'D — Discipline (stability)', color: '#2980b9', values: stimuli.map(s => s.D) },
      { name: 'K — Kinetics (productivity)', color: '#e67e22', values: stimuli.map(s => s.K) },
      { name: 'G — Genius (growth)', color: '#27ae60', values: stimuli.map(s => s.G) }], v => Math.round(v));
    const tot = k => Math.round(stimuli.reduce((a, s) => a + (s[k] || 0), 0));
    charts += '<div style="display:flex;gap:10px;margin:10px 0;">' +
      [['D', 'Discipline', '#2980b9'], ['K', 'Kinetics', '#e67e22'], ['G', 'Genius', '#27ae60']].map(([k, label, c]) =>
        '<div style="flex:1;background:#f8f9fa;border-left:4px solid ' + c + ';border-radius:6px;padding:10px;">' +
        '<div style="font-size:22px;font-weight:800;color:' + c + ';">' + tot(k) + '</div>' +
        '<div style="font-size:11px;color:#57606f;">' + label + ' (week total)</div></div>').join('') + '</div>';
  }
  const med = acts.filter(a => /yoga|meditat|breath|pranayam/i.test((a.name || '') + ' ' + (a.sport_type || ''))).sort(byDateAsc).slice(-12);
  if (med.length) {
    charts += lineChart('Practice duration (min)', med.map(a => dShort(a.start_date_local)),
      [{ name: 'Session', color: '#8e44ad', values: med.map(a => Math.round(a.moving_time / 60)) }], v => Math.round(v));
  } else {
    charts += '<div style="font-size:13px;color:#95a5a6;margin:8px 0;">No meditation/yoga sessions found in Strava yet — D/K/G stimulus points above reflect routine-task practice.</div>';
  }
}

let nutritionCard = '';
if (route === 'lift') {
  let nut = null;
  try { nut = $('Lift Data').first().json.nutrition; } catch (e) { nut = null; }
  if (nut && nut.proteinGoal) {
    const pct = Math.max(0, Math.min(100, Math.round(nut.proteinConsumed / nut.proteinGoal * 100)));
    const hit = nut.proteinLeft <= 0;
    const c = hit ? '#27ae60' : '#2980b9';
    nutritionCard =
      '<div style="background:#f8f9fa;border-left:4px solid ' + c + ';border-radius:8px;padding:12px 14px;margin:14px 0;">'
      + '<div style="font-size:13px;font-weight:600;color:#2c3e50;">\u{1F969} Protein ' + (hit ? 'goal hit' : 'remaining today') + '</div>'
      + '<div style="font-size:26px;font-weight:800;color:' + c + ';margin:2px 0;">' + (hit ? '0g left \u2014 goal met \u2705' : nut.proteinLeft + 'g left') + '</div>'
      + '<div style="font-size:12px;color:#57606f;">' + nut.proteinConsumed + 'g of ' + nut.proteinGoal + 'g eaten (' + pct + '%)</div>'
      + '<div style="margin-top:6px;background:#ecf0f1;border-radius:6px;height:10px;overflow:hidden;"><div style="width:' + pct + '%;height:100%;background:' + c + ';"></div></div>'
      + '</div>';
    if (nut.carbsGoal) {
      const over = nut.carbsExcess > 0;
      const cc = over ? '#c0392b' : '#27ae60';
      const cpct = Math.max(0, Math.min(100, Math.round(nut.carbsConsumed / nut.carbsGoal * 100)));
      nutritionCard +=
        '<div style="background:#f8f9fa;border-left:4px solid ' + cc + ';border-radius:8px;padding:12px 14px;margin:14px 0;">'
        + '<div style="font-size:13px;font-weight:600;color:#2c3e50;">\u{1F35E} Carbs ' + (over ? 'over goal' : 'within goal') + '</div>'
        + '<div style="font-size:26px;font-weight:800;color:' + cc + ';margin:2px 0;">' + (over ? '+' + nut.carbsExcess + 'g excess' : (nut.carbsGoal - nut.carbsConsumed) + 'g headroom') + '</div>'
        + '<div style="font-size:12px;color:#57606f;">' + nut.carbsConsumed + 'g of ' + nut.carbsGoal + 'g goal (' + cpct + '%)</div>'
        + '<div style="margin-top:6px;background:#ecf0f1;border-radius:6px;height:10px;overflow:hidden;"><div style="width:' + cpct + '%;height:100%;background:' + cc + ';"></div></div>'
        + '</div>';
    }
  } else if (nut && nut.summary) {
    nutritionCard = '<div style="font-size:12px;color:#95a5a6;margin:8px 0;">' + esc(nut.summary) + '</div>';
  }
}

const barColor = progress >= 70 ? '#27ae60' : progress >= 40 ? '#f39c12' : '#e74c3c';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8">'
 + '<meta name="viewport" content="width=device-width,initial-scale=1">'
 + '<title>CEO ' + meta.area + ' - End of Day</title></head>'
 + '<body style="margin:0;padding:16px;background:#f4f6f8;font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#2c3e50;">'
 + '<div style="max-width:640px;margin:0 auto;">'
 + '<div style="background:' + meta.color + ';color:#fff;border-radius:12px 12px 0 0;padding:18px 20px;">'
 + '<div style="font-size:13px;opacity:.85;">CEO ' + meta.area + ' &middot; End of Day &middot; ' + esc(ctx.weekday) + ', ' + esc(ctx.dateStr) + '</div>'
 + '<div style="font-size:20px;font-weight:700;margin-top:4px;">' + meta.icon + ' ' + esc(g.body || 'Goal') + '</div>'
 + '</div>'
 + '<div style="background:#fff;border-radius:0 0 12px 12px;padding:20px;box-shadow:0 2px 8px rgba(0,0,0,.08);">'
 + '<div style="display:flex;align-items:center;gap:14px;margin-bottom:6px;">'
 + '<div style="font-size:34px;font-weight:800;color:' + barColor + ';">' + progress + '%</div>'
 + '<div style="flex:1;background:#ecf0f1;border-radius:8px;height:14px;overflow:hidden;">'
 + '<div style="width:' + progress + '%;height:100%;background:' + barColor + ';"></div>'
 + '</div></div>'
 + (summary ? '<div style="font-size:14px;color:#57606f;margin-bottom:16px;">' + esc(summary) + '</div>' : '')
 + nutritionCard + '<h3 style="margin:16px 0 6px;font-size:15px;color:' + meta.color + ';">Trends</h3>'
 + (charts || '<div style="font-size:13px;color:#95a5a6;">No activity data available for charts.</div>')
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:#27ae60;">Strengths</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + li(bullets('Strengths')) + '</ul>'
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:#e67e22;">Weaknesses</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + li(bullets('Weaknesses')) + '</ul>'
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:#2c3e50;">Activity Review</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + li(bullets('Activity Review')) + '</ul>'
 + '<div style="margin-top:18px;font-size:11px;color:#95a5a6;text-align:right;">Generated by CEO End &middot; ' + esc(ctx.dateStr) + '</div>'
 + '</div></div></body></html>';

// date/period resolution (CFO End convention): goal -> webhook query -> today/'day'
function pad(n){ return String(n).padStart(2,'0'); }
const now = new Date();
const today = pad(now.getDate()) + '-' + pad(now.getMonth()+1) + '-' + now.getFullYear();
const q = ($('Webhook').first().json.query) || {};
const date = g.date || q.date || today;
const period = g.period || q.period || 'day';
return { html, date, period, progress };

