parameters.jsCode:
const packed = $('Pack Data').first().json;
let stimuli = [];
try {
  const inner = JSON.parse($input.first().json.result.content[0].text);
  stimuli = (inner.data && inner.data.weekStimuli) || [];
} catch (e) { stimuli = []; }
return { ...packed, stimuli };

const ctx = $input.first().json;
const wt = (ctx.activities || []).filter(a => a.sport_type === 'WeightTraining')
  .sort((a, b) => new Date(a.start_date_local) - new Date(b.start_date_local)).slice(-12);
return wt.map(a => ({ json: { id: a.id_str || String(a.id), name: a.name,
  start_date_local: a.start_date_local, moving_time: a.moving_time } }));

const details = $input.all().map(i => i.json);
const ctx = $('Context').first().json;
const wtDetails = details.map(d => {
  const desc = String(d.description || '');
  const m = desc.match(/([\d,]+)\s*(lbs?|kg)\s*weight lifted/i);
  const ex = desc.match(/(\d+)\s*Exercises?/i);
  return { name: d.name, date: d.start_date_local,
    tonnage: m ? parseInt(m[1].replace(/,/g, ''), 10) : null,
    unit: m ? m[2] : 'lbs',
    exercises: ex ? parseInt(ex[1], 10) : null,
    durationMin: Math.round((d.moving_time || 0) / 60) };
});

// --- MyFitnessPal protein remaining (via mfp wrapper on the docker network) ---
// Query the diary for TODAY in US Eastern. The wrapper defaults to server-UTC 'today',
// but this routine fires in the evening Eastern = already past midnight UTC, so an
// undated call pulled the NEXT day's empty diary -> 0g consumed. Pin the Eastern date.
const mfpDate = $now.setZone('America/New_York').toFormat('yyyy-MM-dd');
let nutrition;
try {
  const mfp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://mfp:8000/diary?date=' + mfpDate,
    headers: { 'X-API-Key': '<<REPLACE_ME>>' },
    json: true,
  });
  const consumed = Math.round((mfp.totals && mfp.totals.protein) || 0);
  const goal = Math.round((mfp.goals && mfp.goals.protein) || 0);
  const left = Math.max(0, goal - consumed);
  const carbs = Math.round((mfp.totals && mfp.totals.carbohydrates) || 0);
  const carbsGoal = Math.round((mfp.goals && mfp.goals.carbohydrates) || 0);
  const carbsExcess = Math.max(0, carbs - carbsGoal);
  nutrition = { proteinConsumed: consumed, proteinGoal: goal, proteinLeft: left,
    carbsConsumed: carbs, carbsGoal: carbsGoal, carbsExcess: carbsExcess,
    summary: (goal ? ('protein target ' + goal + 'g, ' + consumed + 'g eaten, ' + left + 'g remaining today')
                   : 'no protein goal set in MyFitnessPal')
             + (carbsGoal ? ('; carbs ' + carbs + 'g of ' + carbsGoal + 'g target'
                             + (carbsExcess > 0 ? ' (' + carbsExcess + 'g OVER)' : ' (within goal)')) : '') };
} catch (e) {
  nutrition = { proteinConsumed: null, proteinGoal: null, proteinLeft: null,
    carbsConsumed: null, carbsGoal: null, carbsExcess: null,
    summary: 'protein data unavailable (MyFitnessPal fetch failed)' };
}

return { ...ctx, wtDetails, nutrition };

const acts = $('Context').first().json.activities || [];
const wt = acts.filter(a => a.sport_type === 'WeightTraining')
  .sort((a, b) => new Date(a.start_date_local) - new Date(b.start_date_local))
  .slice(-20)
  .map(a => ({ date: String(a.start_date_local).slice(0, 10), name: a.name,
    minutes: Math.round((a.moving_time || 0) / 60) }));
return JSON.stringify(wt);
